package com.andye.warmod.phalanx;
import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.core.BlockPos;
public final class PhalanxStructureAssembly { private static final Map<ServerLevel, Set<BlockPos>> ACTIVE = new WeakHashMap<>(); private PhalanxStructureAssembly(){} public static synchronized void begin(ServerLevel level, Collection<BlockPos> positions){ACTIVE.computeIfAbsent(level,x->new HashSet<>()).addAll(positions);} public static synchronized boolean contains(ServerLevel level, BlockPos position){return ACTIVE.getOrDefault(level,Set.of()).contains(position);} public static synchronized void end(ServerLevel level, Collection<BlockPos> positions){Set<BlockPos> active=ACTIVE.get(level);if(active==null)return;active.removeAll(positions);if(active.isEmpty())ACTIVE.remove(level);} }